def main() -> None:
    changed = 0
    for entry_id, update in REFRESH.items():
        path = BUILD / "terms" / entry_id / "entry.v2.json"
        entry = json.loads(path.read_text(encoding="utf-8"))
        sense_updates = update.get("senses") or [update]
        if len(sense_updates) != len(entry["Senses"]):
            raise RuntimeError(f"sense count mismatch for {entry_id}")
        for si, (sense, sense_update) in enumerate(zip(entry["Senses"], sense_updates)):
            sense["Explanation"] = sense_update["explanation"]
            sense["Note"] = sense_update["note"]
            notes = sense_update["occurrence_notes"]
            if len(notes) != len(sense.get("Occurrences") or []):
                raise RuntimeError(f"occurrence-note count mismatch for {entry_id} sense {si}")
            for occurrence, note in zip(sense["Occurrences"], notes):
                occurrence["AttributionNote"] = note
        path.write_text(json.dumps(entry, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        changed += 1
        print(f"updated {entry_id}")
    print(f"updated files: {changed}")


if __name__ == "__main__":
    main()
